from roman import to_roman

# Independent reference implementation (different algorithm)
def ref(n):
    vals = [(1000,"M"),(900,"CM"),(500,"D"),(400,"CD"),(100,"C"),(90,"XC"),
            (50,"L"),(40,"XL"),(10,"X"),(9,"IX"),(5,"V"),(4,"IV"),(1,"I")]
    s = ""
    for v, sym in vals:
        while n >= v:
            s += sym; n -= v
    return s

# Standard validity rules: no symbol repeated >3x, no invalid pairs
bad_pairs = ["IIII","VV","XXXX","LL","CCCC","DD","IL","IC","ID","IM","VX","VL","VC","VD","VM","XD","XM","LC","LD","LM","DM","IIV","IIX"]

errs = 0
for n in range(1, 4000):
    got = to_roman(n)
    exp = ref(n)
    if got != exp:
        print("MISMATCH", n, got, exp); errs += 1
    for p in bad_pairs:
        if p in got:
            print("INVALID", n, got, p); errs += 1
print("spot checks:", to_roman(4), to_roman(9), to_roman(40), to_roman(90), to_roman(400), to_roman(900), to_roman(1994), to_roman(3999))
print("total errors:", errs)

# Range check / exception unchanged
for n in (0, -1, 4000):
    try:
        to_roman(n)
        print("NO RAISE for", n); errs += 1
    except ValueError as e:
        print(f"ValueError({n}):", e)
print("OK" if errs == 0 else "FAILED")
EOF

